import re
from .errors import LexError

class Token :
    def __init__(self, kind: str, value, position: int):
        self.kind = kind
        self.value = value
        self.position = position

KEYWORDS = {"true", "false", "and", "or", "not"}

def tokenize(source: str):
    tokens = []
    pos = 0
    while pos < len(source):
        c = source[pos]
        if c.isspace():
            pos += 1
            continue
        if c == "#":
            pos = source.find("\n", pos)
            if pos == -1:
                pos = len(source)
            continue # comment to end of line
        if c.isdigit() or (c == "." and pos + 1 < len(source) and source[pos + 1].isdigit()):
            start = pos
            while pos < len(source) and source[pos].isdigit():
                pos += 1
            if pos < len(source) and source[pos] == ".":
                if pos + 1 < len(source) and source[pos + 1].isdigit():
                    pos += 1
                    while pos < len(source) and source[pos].isdigit():
                        pos += 1
                else:
                    raise LexError("number may not end with .", start)
            if pos < len(source) and source[pos].lower() in "e":
                pos += 1
                if pos < len(source) and source[pos] in "+-":
                    pos += 1
                if pos < len(source) and source[pos].isdigit():
 while pos < len(source) and source[pos].isdigit():
                        pos += 1
                else:
                    raise LexError("invalid exponent", start)
            val = float(source[start:pos])
            tokens.append(Token("NUMBER", val, start))
            continue
        if c == '"':
            start = pos # position of opening quote
            pos += 1
            s = []
            while pos < len(source):
                if source[pos] == "\\":
                    pos += 1
                    if pos >= len(source):
                        raise LexError("unterminated string", start)
                    esc = source[pos]
                    if esc == "n":
                        s.append("\n")
                    elif esc == "t":
                        s.append("\t")
                    elif esc == "r":
                        s.append("\r")
                    elif esc == "\\":
                        s.append("\\")
                    elif esc == '"':
                        s.append('"')
                    else:
                        raise Lex Error(f"bad escape {esc!r}", pos)
                    pos += 1
                elif source[pos] == "\n":
                    raise LexError("newline in string", start)
                elif source[pos] == '"':
                    pos += 1
                    break
                else:
                    s.append(source[pos])
 pos += 1
            tokens.append(Token("STRING", "".join(s), start))
            continue
        if c.isalpha() or c == "_":
            start = pos
            while pos < len(source) and (source[pos].isalnum() or source[pos] == "_"):
                pos +=  1
            name = source[start:pos]
            if name in KEYWORDS:
                tokens.append(Token("KEYWORD", name, start))
            else:
                tokens.append(Token("IDENT", name, start))
            continue
        if c in "+-*/%^=<>!(),":
            if c == "=":
                if pos + 1 < len(source) and source[pos + 1] == "=":
                    tokens.append(Token("OP", "==", pos))
                    pos += 1
                else:
                    raise LexError("single =", pos)
            elif c == "!":
                if pos +  1 < len(source) and source[pos + 1] == "=":
                    tokens.append(Token("OP", "!=", pos))
                    pos += 1
                else:
                    raise LexError("bare !", pos)
            else:
                tokens.append(Token("OP", c, pos))
                pos +=  1
            continue
        raise LexError("unexpected character", pos)
    return tokens
