    def __init__(self, value: bool, position: int):
        self.value = value
        self.position = position

class Variable(AST):
    def __init__(self, name: str, position: int):
        self.name = name
        self.position = position

class Call(AST):
    def __init__(self, name: str, args: list, position: int):
        self.name = name
        self.args = args
        self.position = position

class Unary(AST):
    def __init__(self, op: str, expr: AST, position: int):
        self.op = op
        self.expr = expr
 self.position = position

class Binary(AST):
    def __init__(self, op: str, left: AST, right: AST, position: int):
        self.op = op
        self.left = left
        self.right = right
        self.position = position

class Logical(AST):
    def __init__(self, op: str, left: AST, right: AST, position: int):
        self.op = op
        self.left = left
        self.right = right
        self.position = position

def parse(source: str):
    tokens = tokenize(source)
    if not tokens:
        raise ParseError("empty source", 0)
    p = Parser(tokens, source)
    try:
        ast = p.expr()
        if p.i < len(p.tokens):
            raise ParseError("trailing input", p.tokens[p.i].position)
        return ast
    except ParseError:
        raise
    except Exception as e:
        raise ParseError(str(e), p.pos())

class Parser:
    def __init__(self, tokens, source):
        self.tokens = tokens
        self.source = source
        self.i = 0

    def peek(self):
        return self.tokens[self.i] if self.i < len(self.tokens) else None

    def advance(self):
        self.i += 1

    def pos(self):
        if self.peek():
            return self.peek().position
        return len(self.source)

    def expect(self, kind, value=None):
        t = self.peek()
        if not t or t .kind != kind or (value is not None and t.value != value):
            raise ParseError("unexpected token", self.pos())
        self.advance()

    def expr(self):
