def _assignment(line: str):
    i = 0
    n = len(line)
    while i < n and line[i] in " \t":
        i += 1
    if i >= n or not (line[i].isalpha() or line[i] == "_"):
        return None
    start = i
    i += 1
    while i < n and (line[i].isalnum() or line[i] == "_"):
