    while i < n and line[i] in " \t":
        i += 1
    if i < n and line[i] == "=" and (i + 1 >= n or line[i + 1] != "="):
        return name, line[i + 1 :]
    return None


def main(argv=None) -> int:
    env = {}
    for line in sys.stdin:
        if line.endswith("\n"):
            line = line[:-1]
        if line.endswith("\r"):
            line = line[:-1]
        stripped = line.strip()
        if stripped == "":
