import math

from minilang.errors import EvalError, LexError
from minilang.lexer import tokenize


def _is_number(value) -> bool:
    return isinstance(value, float) and not isinstance(value, bool)


def _arity_exact(name: str, args: list, expected: int):
    n = len(args)
    if n != expected:
        raise EvalError(f"{name}() takes {expected} argument(s), got {n}")


def _arity_min(name: str, args: list, minimum: int):
    n = len(args)
    if n < minimum:
        raise EvalError(f"{name}() takes at least {minimum} argument(s), got {n}")


def _require_number(name: str, value, label="argument"):
    if not _is_number(value):
        raise EvalError(f"{name}() {label} must be a number")


def format_number(value: float) -> str:
    if math.isfinite(value) and value.is_integer():
        return str(int(value))
    return repr(value)


def format_value(value) -> str:
    if isinstance(value, bool):
        return "true" if value else "false"
    if isinstance(value, float):
        return format_number(value)
    if isinstance(value, str):
        escaped = (
            value.replace("\\", "\\\\")
            .replace("\n", "\\n")
            .replace("\t", "\\t")
            .replace("\r", "\\r")
            .replace('"', '\\"')
        )
        return f'"{escaped}"'
    raise EvalError(f"unsupported value: {value!r}")


def builtin_abs(args):
    _arity_exact("abs", args, 1)
    _require_number("abs", args[0])
    return abs(args[0])


def builtin_min(args):
    _arity_min("min", args, 1)
    for a in args:
        _require_number("min", a)
    return min(args)


def builtin_max(args):
    _arity_min("max", args, 1)
    for a in args:
        _require_number("max", a)
    return max(args)


def builtin_round(args):
    n = len(args)
    if n not in (1, 2):
        raise EvalError(f"round() takes 1 or 2 argument(s), got {n}")
    _require_number("round", args[0])
    if n == 1:
        return float(round(args[0]))
    _require_number("round", args[1], "ndigits")
    ndigits = args[1]
    if not ndigits.is_integer():
        raise EvalError("round() ndigits must be a whole number")
    return float(round(args[0], int(ndigits)))


def builtin_len(args):
    _arity_exact("len", args, 1)
    if not isinstance(args[0], str):
        raise EvalError("len() argument must be a string")
    return float(len(args[0]))


def builtin_upper(args):
    _arity_exact("upper", args, 1)
    if not isinstance(args[0], str):
        raise EvalError("upper() argument must be a string")
    return args[0].upper()


def builtin_lower(args):
    _arity_exact("lower", args, 1)
    if not isinstance(args[0], str):
        raise EvalError("lower() argument must be a string")
    return args[0].lower()


def builtin_str(args):
    _arity_exact("str", args, 1)
    value = args[0]
    if isinstance(value, bool):
        return "true" if value else "false"
    if _is_number(value):
        return format_number(value)
    if isinstance(value, str):
        return value
    raise EvalError("str() argument must be a number, string, or boolean")


def builtin_num(args):
    _arity_exact("num", args, 1)
    if not isinstance(args[0], str):
        raise EvalError("num() argument must be a string")
    # Interpret using minilang number tokens so "1." and junk are rejected.
    try:
        tokens = tokenize(args[0])
    except LexError:
        raise EvalError("cannot parse number") from None
    if len(tokens) != 1 or tokens[0].kind != "NUMBER":
        raise EvalError("cannot parse number")
    return tokens[0].value


FUNCTIONS = {
    "abs": builtin_abs,
    "min": builtin_min,
    "max": builtin_max,
    "round": builtin_round,
    "len": builtin_len,
    "upper": builtin_upper,
    "lower": builtin_lower,
    "str": builtin_str,
    "num": builtin_num,
}

import math

from minilang.builtins import FUNCTIONS, format_value
from minilang.errors import EvalError
from minilang.parser import Binary, BoolLit, Call, NumberLit, StringLit, Unary, Variable, parse

_ALLOWED = (float, str, bool)


def _is_number(value) -> bool:
    return isinstance(value, float) and not isinstance(value, bool)


def evaluate(source: str, env: dict | None = None):
    tree = parse(source)
    return eval_node(tree, env)


def eval_node(node, env: dict | None):
    if isinstance(node, NumberLit):
        return node.value
    if isinstance(node, StringLit):
        return node.value
    if isinstance(node, BoolLit):
        return node.value
    if isinstance(node, Variable):
        return _lookup_var(node.name, env)
    if isinstance(node, Unary):
        return _eval_unary(node, env)
    if isinstance(node, Binary):
        return _eval_binary(node, env)
    if isinstance(node, Call):
        return _eval_call(node, env)
    raise EvalError(f"unknown AST node: {type(node).__name__}")


def _lookup_var(name: str, env: dict | None):
    if env is None or name not in env:
        raise EvalError(f"undefined variable: {name}")
    value = env[name]
    if not isinstance(value, _ALLOWED) or type(value) not in (float, str, bool):
        raise EvalError(f"unsupported value for {name}: {value!r}")
    return value


def _eval_unary(node: Unary, env):
    if node.op == "not":
        operand = eval_node(node.operand, env)
        if not isinstance(operand, bool):
            raise EvalError("not requires a boolean")
        return not operand
    if node.op == "-":
        operand = eval_node(node.operand, env)
        if not _is_number(operand):
            raise EvalError("unary minus requires a number")
        return -operand
    raise EvalError(f"unknown unary operator: {node.op}")


def _eval_binary(node: Binary, env):
    op = node.op
    if op in ("and", "or"):
        left = eval_node(node.left, env)
        if not isinstance(left, bool):
            raise EvalError(f"{op} requires boolean operands")
        if op == "and":
            if not left:
                return False
        else:
            if left:
                return True
        right = eval_node(node.right, env)
        if not isinstance(right, bool):
            raise EvalError(f"{op} requires boolean operands")
        return right

    left = eval_node(node.left, env)
    right = eval_node(node.right, env)

    if op == "+":
        if _is_number(left) and _is_number(right):
            return left + right
        if isinstance(left, str) and isinstance(right, str):
            return left + right
        raise EvalError("+ requires two numbers or two strings")
    if op == "-":
        _require_nums(op, left, right)
        return left - right
    if op == "*":
        _require_nums(op, left, right)
        return left * right
    if op == "/":
        _require_nums(op, left, right)
        if right == 0.0:
            raise EvalError("division by zero")
        return left / right
    if op == "%":
        _require_nums(op, left, right)
        if right == 0.0:
            raise EvalError("modulo by zero")
        return left % right
    if op == "^":
        _require_nums(op, left, right)
        try:
            result = left ** right
        except ZeroDivisionError:
            raise EvalError("invalid power") from None
        except OverflowError:
            raise EvalError("invalid power") from None
        if isinstance(result, complex) or (
            isinstance(result, float) and math.isnan(result)
        ):
            raise EvalError("power result is not a real number")
        if isinstance(result, bool) or not isinstance(result, (float, int)):
            raise EvalError("power result is not a real number")
        return float(result)
    if op in ("==", "!="):
        equal = _values_equal(left, right)
        return equal if op == "==" else (not equal)
    if op in ("<", "<=", ">", ">="):
        if _is_number(left) and _is_number(right):
            pair = (left, right)
        elif isinstance(left, str) and isinstance(right, str):
            pair = (left, right)
        else:
            raise EvalError(f"{op} requires two numbers or two strings")
        a, b = pair
        if op == "<":
            return a < b
        if op == "<=":
            return a <= b
        if op == ">":
            return a > b
        return a >= b
    raise EvalError(f"unknown operator: {op}")


def _values_equal(left, right) -> bool:
    if isinstance(left, bool) or isinstance(right, bool):
        return isinstance(left, bool) and isinstance(right, bool) and left is right
    return type(left) is type(right) and left == right


def _require_nums(op, left, right):
    if not (_is_number(left) and _is_number(right)):
        raise EvalError(f"{op} requires numbers")


def _eval_call(node: Call, env):
    name = node.name
    if name == "if":
        if len(node.args) != 3:
            raise EvalError(f"if() takes 3 argument(s), got {len(node.args)}")
        cond = eval_node(node.args[0], env)
        if not isinstance(cond, bool):
            raise EvalError("if() condition must be a boolean")
        return eval_node(node.args[1] if cond else node.args[2], env)
    if name not in FUNCTIONS:
        raise EvalError(f"undefined function: {name}")
    args = [eval_node(arg, env) for arg in node.args]
    return FUNCTIONS[name](args)


